/* ===== module: formulas/progression-preview-grid.js ===== */
/* FORK: program-level progression preview grid (Top-16 #15 remainder;
   the program-wide companion to v1.964's forkPreviewTrajectory in
   workout/progression.js, which previews the next sessions for ONE
   exercise from a suggestion card). Pure functions only — no DOM, no
   state, no storage — so the unit suite can load this file alone.

   forkProgramPreviewGrid(program, histories, config) answers, for
   every exercise in a program: "if every session goes exactly as
   suggested, what does the top set look like over the next few
   weeks?" It is arithmetic, not engine simulation — the same small
   arithmetic as forkPreviewTrajectory, duplicated here on purpose
   (this module mirrors progression.js; progression.js is NOT edited)
   and extended from a starting top set instead of a suggestion:

   - linear: add the increment every session. A 'pct' increment
     compounds per session, rounded to the nearest 0.5 each step
     (exactly as forkPreviewTrajectory rounds).
   - rpe (and an explicit 'bodyweight' scheme): reps climb by 1 until
     the top of the range, then the weight steps by the increment and
     reps reset to the bottom of the range. A weightless top set
     (weight 0/null — bodyweight work) stays weightless: cells carry
     weight null and the label is reps-only. 'bodyweight' never steps
     a weight at the range top; it just resets reps.
   - a profile flagged repsOnly never steps the weight either: reps
     climb by 1 per session and the weight is carried unchanged.

   Transparency rule (inherited from #15): a cell is only ever a
   number this arithmetic can state EXACTLY. Everything else is a
   status, never a guessed number:
   - { status: 'no-history' } — no usable top set was supplied for
     the exercise in `histories` (checked first: without a starting
     point there is nothing to project, whatever the scheme).
   - { status: 'unstated', reason } — the scheme cannot be stated
     exactly: '%1RM' work ('onerm') with NO stored Training Max,
     time-based work (mode 'time'), progression 'off', any unknown
     scheme, linear work with no load to add to, an RPE profile
     whose reps/range cannot be read, or a range whose top is below
     its bottom.
   S13: '%1RM' work WITH a stored Training Max (progression
   .trainingMax, or the listing's own sets carrying per-set % of TM)
   IS statable exactly, with no logged history: each week's top-set
   weight is TM x the week's resolved % (top set's own % ->
   exercise % override -> weekly wave % -> program flat % -> 75)
   snapped to the increment grid, deload weeks scaled by the
   deload % — the engine's onermRx + deload arithmetic, mirrored.

   Scheduling model (stated on the result, see `assumptions`):
   each program workout occurs `sessionsPerWeekPerWorkout` times per
   week (default 1), in the order listed in the program. One cell per
   week; when a workout runs more than once a week the cell shows
   that week's LAST session target. Week 1 is the first session after
   the supplied top set — i.e. week 1 is the step
   forkPreviewTrajectory's caller would call the suggestion, and
   later weeks continue the same trajectory.

   FORK v1.991.33 (R1 item 5): a listing may carry its OWN starting
   point as `history` (same { weight, reps } shape as a `histories`
   entry), which takes precedence over the shared map — the adapter
   supplies the listing's program-slot history, so two slots of one
   exercise no longer share a starting point. A listing history
   flagged `prescription: true` is a PRESCRIBED top set, not a past
   performance: the first session cell IS the prescription itself
   (no step applied) and the trajectory steps from session 2 on —
   feeding a prescription through the past-top-set path would skip
   the prescribed session by one step.
   FORK v1.991.58 (FR-154): two honesty rules on top of that —
   a prescription-flagged history states its week-1 cell even in
   the branches that cannot project later weeks (linear with no
   load, %1RM, …), and a reps count of 0 reads as "absent", so a
   weight-only prescription never renders as "140 × 0".
   FORK v1.992.22 (P2-8a, fix-list #32): under the linear scheme a
   performed top set above a closed range's top is clamped to the
   top before stepping — an AMRAP-style performance is never
   adopted as the ongoing rep target (the engine's own clamp on
   the same basis). Prescriptions and open ranges are exempt.

   Input shape:
     program = {
       name?: string,
       progression?: object,            // program-level defaults
       workouts: [{
         name?: string,
         exercises?: [{                 // or workout.template.exercises
           exerciseId, name?,
           tracking?, mode?,            // 'time' work is unstated
           history?,                    // per-listing top set (see above);
                                        // { weight, reps, prescription? }
           progression?: { scheme, min, max, openTop, repsOnly,
                           incrementType, incrementValue, mode,
                           trainingMax?, percentOf1RM? },
           sets?: [{ r?, pct?, tags? }]   // S13: prescribed sets;
                           // the top (highest-%) non-warm-up set's
                           // pct/reps state the %1RM top set
         }]
       }]
     }
     histories = { [exerciseId]: { weight, reps } }  // current top set;
                    a Map or an array of {exerciseId, weight, reps}
                    is also accepted. weight may be 0/null for
                    bodyweight work (reps then carry the history).
     config = {
       weeks?: number,                    // default 4, clamped 1..12
       sessionsPerWeekPerWorkout?: number,// default 1, clamped 1..7
       defaults?: object,                 // fallback progression fields
     }

   Missing progression fields resolve per field, in order:
   exercise profile -> program.progression -> config.defaults ->
   built-in defaults { scheme: 'linear', min: 6, max: 12,
   incrementType: 'lb', incrementValue: 5 } (the app's own defaults:
   DEFAULT_PROGRESSION_SETUP's scheme/increment/defaultRange). An
   openTop profile with no explicit max climbs reps without a top.

   Output shape:
     {
       programName: string,
       weeks, sessionsPerWeekPerWorkout,
       assumptions: [string, ...],   // printable verbatim by the UI
       rows: [{
         exerciseId, name, workoutName, workoutIndex,
         scheme, min, max, incrementType, incrementValue,
         cells: [{ week, status, weight, reps, label, reason? }]
                  // status 'ok' | 'no-history' | 'unstated';
                  // weight/reps are null unless status is 'ok'
                  // (bodyweight 'ok' cells have weight null by
                  // design and a reps-only label).
       }]
     }
   One row per exercise OCCURRENCE, in program order: an exercise
   listed in two workouts (or twice in one) gets a row per listing,
   because each listing may carry its own progression profile.
   The function is total: null/garbage input yields empty rows and
   status cells, never a throw. */

/* Built-in fallback progression fields (see header). */
const FORK_PREVIEW_GRID_DEFAULTS = {
  scheme: 'linear', min: 6, max: 12, incrementType: 'lb', incrementValue: 5,
};

/* Strict numeric read: null/undefined/''/booleans/non-finite -> null.
   (Number('') is 0 and Number(true) is 1; neither is a top set.) */
function forkPreviewGridNum(value) {
  if (value == null || value === '' || typeof value === 'boolean') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

/* First present (non-null, non-'') value of `key` across `sources`. */
function forkPreviewGridField(sources, key) {
  for (const src of sources) {
    if (src && typeof src === 'object') {
      const v = src[key];
      if (v !== undefined && v !== null && v !== '') return v;
    }
  }
  return undefined;
}

/* Display formatting for labels: integers stay integers, halves and
   other steps keep at most 3 decimals (105, 102.5, 107.25). */
function forkPreviewGridFmt(n) {
  return String(Math.round(Number(n) * 1000) / 1000);
}

/* Cell label: a number-bearing label only for statable targets. */
function forkPreviewGridLabel(weight, reps) {
  if (weight != null && weight > 0 && reps != null) {
    return forkPreviewGridFmt(weight) + ' × ' + forkPreviewGridFmt(reps);
  }
  if (weight != null && weight > 0) return forkPreviewGridFmt(weight);
  if (reps != null) return forkPreviewGridFmt(reps) + ' reps';
  return '—';
}

/* The printable assumptions. The first line reflects the actual
   sessions-per-week the grid was built with, so the UI can print
   the array verbatim without ever stating a schedule it did not
   use. */
function forkPreviewGridAssumptions(sessionsPerWeek) {
  const schedule = sessionsPerWeek === 1
    ? 'Each program workout occurs once per week, in the order listed in the program.'
    : 'Each program workout occurs ' + sessionsPerWeek + ' times per week, in the order listed in the program; each weekly cell shows that week\'s last session target.';
  return [
    schedule,
    /* FORK v1.991.7 (DQ-1): week-indexed variation keys off the
       calendar week the session happens in, never its place in
       the rotation — stated here, where the grid's other
       assumptions live, so doing a session early or late can
       never silently change which week's targets it uses. */
    'Week-by-week changes (waves, deload weeks) follow the calendar week a session happens in, not its place in the rotation.',
    /* FORK v1.991.17 (FR-76 follow-up): the "Every session goes
       exactly as suggested" line is REMOVED — it was the grid-side
       twin of the explainer sentence FR-76 struck from the card,
       the same bloat species (audit ui-audit-2 §3.3). */
    'Targets start from the most recent top set supplied in histories; week 1 is the next session after that top set.',
    'Linear targets add the increment every session; RPE targets add a rep until the top of the range, then add the increment and reset reps to the bottom of the range.',
    'Cells that cannot be stated exactly — no usable history, or %1RM work with no Training Max set — show a status instead of a target, never a guessed number.',
  ];
}

/* Resolve one exercise listing's effective progression profile.
   Per-field resolution order is documented in the header. */
function forkPreviewGridProfile(entry, program, config) {
  const defaults = (config && (config.defaults || config.defaultProgression || config.progression)) || null;
  const sources = [
    entry && entry.progression,
    program && program.progression,
    defaults,
  ];
  const schemeRaw = forkPreviewGridField(sources, 'scheme');
  const scheme = (typeof schemeRaw === 'string' && schemeRaw.trim())
    ? schemeRaw.trim().toLowerCase().replace(/\s+/g, '')
    : FORK_PREVIEW_GRID_DEFAULTS.scheme;
  const minNum = forkPreviewGridNum(forkPreviewGridField(sources, 'min'));
  const maxRaw = forkPreviewGridField(sources, 'max');
  const maxNum = forkPreviewGridNum(maxRaw);
  const openTop = forkPreviewGridField(sources, 'openTop') === true;
  /* FORK v1.992.15 (FR-204): an EXPLICIT blank max — a null in the
     first source that carries a max slot at all — is an open
     range, not an absent one. The field reader skips nulls, so a
     blank max used to fall through to a later source's max or the
     built-in 12, and the cells capped and reset at a top nobody
     set. AMRAP sources are exempt: their max is null by mechanism,
     not by entry, and their grid resolution is unchanged. */
  let explicitOpenMax = false;
  for (const src of sources) {
    if (src && typeof src === 'object' && src.max !== undefined && src.max !== '') {
      explicitOpenMax = src.max === null && src.amrap !== true;
      break;
    }
  }
  /* openTop with no explicit max anywhere: reps climb without a top. */
  const max = ((openTop && maxRaw === undefined) || (explicitOpenMax && minNum != null))
    ? Infinity
    : (maxNum != null ? maxNum : FORK_PREVIEW_GRID_DEFAULTS.max);
  const incTypeRaw = forkPreviewGridField(sources, 'incrementType');
  const incValNum = forkPreviewGridNum(forkPreviewGridField(sources, 'incrementValue'));
  const modeRaw = (entry && (entry.tracking || entry.mode))
    || forkPreviewGridField(sources, 'mode');
  /* S13: the %1RM statement pieces. A % exercise is statable
     exactly when a Training Max is stored: the top-set weight for a
     week is TM x % on the app's increment grid, with % resolving
     set -> exercise -> weekly wave -> program flat -> 75 (the
     engine's onermRx precedence, mirrored). trainingMax /
     percentOf1RM are per-exercise fields; the wave arrays and
     deload % are program-level (config.defaults last). The listing's
     own sets contribute the TOP set's %: the highest % among its
     non-warm-up sets, plus that set's authored reps. */
  const entryProg = (entry && entry.progression) || null;
  const programProg = (program && program.progression) || null;
  const tmNum = forkPreviewGridNum(forkPreviewGridField([entryProg], 'trainingMax'))
    ?? forkPreviewGridNum(forkPreviewGridField([entryProg], 'manual1RM'));
  let topPct = null, topReps = null;
  const entrySets = (entry && Array.isArray(entry.sets)) ? entry.sets : [];
  for (const s of entrySets) {
    if (!s || typeof s !== 'object') continue;
    const tags = Array.isArray(s.tags) ? s.tags : [];
    if (tags.some(t => String(t).toLowerCase() === 'warmup')) continue;
    const p = forkPreviewGridPctOrNull(s.pct);
    if (p != null && (topPct == null || p > topPct)) {
      topPct = p;
      const r = forkPreviewGridNum(s.r != null ? s.r : s.reps);
      topReps = r != null && r > 0 ? r : null;
    }
  }
  return {
    scheme,
    min: minNum != null ? minNum : FORK_PREVIEW_GRID_DEFAULTS.min,
    max,
    incrementType: (typeof incTypeRaw === 'string' && incTypeRaw) ? incTypeRaw : FORK_PREVIEW_GRID_DEFAULTS.incrementType,
    incrementValue: incValNum != null ? incValNum : FORK_PREVIEW_GRID_DEFAULTS.incrementValue,
    repsOnly: forkPreviewGridField(sources, 'repsOnly') === true,
    mode: (typeof modeRaw === 'string' && modeRaw) ? modeRaw.trim().toLowerCase() : null,
    trainingMax: tmNum != null && tmNum > 0 ? tmNum : null,
    itemPercentOf1RM: forkPreviewGridPctOrNull(entryProg && entryProg.percentOf1RM),
    programPercentOf1RM: forkPreviewGridPctOrNull(forkPreviewGridField([programProg, defaults], 'percentOf1RM')),
    pctWave: forkPreviewGridField([programProg, defaults], 'pctWave') === true,
    weeklyPcts: forkPreviewGridField([programProg, defaults], 'weeklyPcts'),
    weeklyDeloads: forkPreviewGridField([programProg, defaults], 'weeklyDeloads'),
    deloadPct: (() => {
      const d = forkPreviewGridNum(forkPreviewGridField([programProg, defaults], 'deloadPct'));
      return d != null && d > 0 ? Math.min(80, Math.max(40, Math.round(d * 100) / 100)) : 60;
    })(),
    topPct,
    topReps,
  };
}

/* S13: a usable % (finite, > 0), decimal-clamped to 1–100 — or
   null, mirroring program-math.js's pctValueOrNull so a resolution
   chain falls through instead of landing on a default. */
function forkPreviewGridPctOrNull(value) {
  if (value == null || value === '' || typeof value === 'boolean') return null;
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? Math.min(100, Math.max(1, Math.round(n * 100) / 100)) : null;
}

/* S13: the weekly wave % for a week — mirrors programPctForWeek
   (program-math.js): inert unless the wave is on; cycles across
   the program length. */
function forkPreviewGridWeekPct(profile, week) {
  if (!profile.pctWave) return null;
  const arr = profile.weeklyPcts;
  if (!Array.isArray(arr) || !arr.length) return null;
  const w = Math.max(1, Number(week) || 1);
  return forkPreviewGridPctOrNull(arr[(w - 1) % arr.length]);
}

/* S13: mirrors isDeloadWeek (program-math.js): a wave-flag deload
   only counts while the wave is on. */
function forkPreviewGridIsDeloadWeek(profile, week) {
  if (!profile.pctWave) return false;
  const flags = profile.weeklyDeloads;
  const w = Math.max(1, Number(week) || 0);
  return Array.isArray(flags) && flags.length > 0 && !!flags[(w - 1) % flags.length];
}

/* S13: mirrors snapToIncrement (increments.js) in this core's own
   numeric space: percent increments snap to the 5-unit grid, fixed
   increments to the increment grid, no usable increment to whole
   units. (The app's metric percent grid is 2.5 kg in canonical lb;
   this core works in the display-agnostic space its other
   arithmetic uses — imperial is exact.) */
function forkPreviewGridSnapPct(raw, profile) {
  if (!(raw > 0)) return 0;
  if (profile.incrementType === 'pct' || profile.incrementType === 'percent') {
    return Math.round(raw / 5) * 5;
  }
  const v = profile.incrementValue;
  if (!(v > 0)) return Math.round(raw);
  return Math.round(raw / v) * v;
}

/* S13: the % a week's top set resolves to — the listing's top
   set's own % first (per-set % overrides the weekly %), then the
   exercise override, the wave, the program flat %, then 75. The
   same chain as program-math.js's resolveSetPct. */
function forkPreviewGridResolvePct(profile, week) {
  return profile.topPct
    ?? profile.itemPercentOf1RM
    ?? forkPreviewGridWeekPct(profile, week)
    ?? profile.programPercentOf1RM
    ?? 75;
}

/* Look a top set up in `histories` (plain object, Map, or array). */
function forkPreviewGridHistory(histories, exerciseId) {
  if (exerciseId == null || histories == null) return undefined;
  if (typeof Map !== 'undefined' && histories instanceof Map) return histories.get(exerciseId);
  if (Array.isArray(histories)) {
    return histories.find(h => h && (h.exerciseId === exerciseId || h.id === exerciseId));
  }
  if (typeof histories === 'object') return histories[exerciseId];
  return undefined;
}

/* Build the weekly cells for one resolved row. The per-session step
   below mirrors forkPreviewTrajectory in workout/progression.js
   (duplicated deliberately — see the header): linear adds the
   increment ('pct' compounds, rounded to halves); rpe climbs reps
   to the range top, then steps the weight by the increment ('pct'
   steps are computed off the CURRENT weight, rounded to halves) and
   resets reps to the range bottom; a weightless rpe top set reports
   weight null. */
function forkPreviewGridCells(profile, history, weeks, sessionsPerWeek) {
  /* History first: no usable top set -> no projection, any scheme.
     A top set is usable with a load, or with reps (bodyweight).
     A reps count of 0 carries nothing either (a weight-only typed
     prescription, or a logged set with untyped reps): normalising
     it to "absent" keeps every cell honest — before FORK v1.991.58
     (FR-154) a weight-only prescription rendered its weeks as
     "140 × 0". */
  const hWeight = history && typeof history === 'object'
    ? forkPreviewGridNum(history.weight != null ? history.weight : history.w)
    : null;
  const hRepsRaw = history && typeof history === 'object'
    ? forkPreviewGridNum(history.reps != null ? history.reps : history.r)
    : null;
  const hReps = hRepsRaw != null && hRepsRaw > 0 ? hRepsRaw : null;
  const fromPrescription = !!(history && typeof history === 'object' && history.prescription === true);

  /* FORK v1.991.58 (FR-154): a prescription IS a statement about
     week 1 even when nothing can be said about later weeks. The
     unstated branches below (linear with no load, %1RM, off,
     holds, unknown scheme) used to return their status for ALL
     weeks, so a slot whose only statement is its prescription —
     exactly what its Progression dialog shows as the starting
     point — previewed as uniformly "Not previewable". Week 1 now
     carries the prescription itself; weeks 2+ keep the status. */
  const rxCell = fromPrescription && (hWeight > 0 || hReps != null)
    ? { week: 1, status: 'ok', weight: hWeight > 0 ? hWeight : null, reps: hReps,
        label: forkPreviewGridLabel(hWeight > 0 ? hWeight : null, hReps) }
    : null;

  const statusCells = (status, label, reason) => {
    const cells = [];
    for (let week = 1; week <= weeks; week++) {
      if (rxCell && week === 1) { cells.push(rxCell); continue; }
      const cell = { week, status, weight: null, reps: null, label };
      if (reason) cell.reason = reason;
      cells.push(cell);
    }
    return cells;
  };

  /* S13: a %1RM listing WITH a stored Training Max is statable
     exactly — no logged history required, because the TM is the
     starting point (the engine's onermRx prescribes from a manual
     TM with no history too). Each week's top-set weight is
     TM x the week's resolved % on the increment grid; a wave-flag
     deload week scales it by the deload %, mirroring the engine's
     deload branch. Reps: the prescription's top-set reps, else the
     latest top set's reps clamped into the range (the engine's
     %1RM rep rule), else the range floor. Without a TM the scheme
     stays 'unstated' below — a % of an unknown max is not a
     number this grid may state. */
  if ((profile.scheme === 'onerm' || profile.scheme === '%1rm' || profile.scheme === 'percent' || profile.scheme === 'percentage')
      && profile.mode !== 'time' && profile.mode !== 'seconds'
      && profile.trainingMax != null && profile.trainingMax > 0) {
    const reps = profile.topReps != null
      ? profile.topReps
      : (hReps != null
        ? Math.min(Number.isFinite(profile.max) ? profile.max : hReps, Math.max(profile.min, hReps))
        : profile.min);
    const cells = [];
    for (let week = 1; week <= weeks; week++) {
      const pct = forkPreviewGridResolvePct(profile, week);
      let w = forkPreviewGridSnapPct(profile.trainingMax * pct / 100, profile);
      if (forkPreviewGridIsDeloadWeek(profile, week)) {
        w = forkPreviewGridSnapPct(w * profile.deloadPct / 100, profile);
      }
      cells.push({
        week,
        status: 'ok',
        weight: w > 0 ? w : null,
        reps,
        label: forkPreviewGridLabel(w > 0 ? w : null, reps),
      });
    }
    return cells;
  }

  if (!history || typeof history !== 'object' || !(hWeight > 0 || hReps != null)) {
    return statusCells('no-history', 'No history yet');
  }

  /* Schemes / modes whose targets cannot be stated exactly. */
  const scheme = profile.scheme;
  if (profile.mode === 'time' || profile.mode === 'seconds' || scheme === 'time') {
    return statusCells('unstated', 'Not previewable', 'time');
  }
  if (scheme === 'onerm' || scheme === '%1rm' || scheme === 'percent' || scheme === 'percentage') {
    return statusCells('unstated', 'Not previewable', 'onerm');
  }
  if (scheme === 'off') return statusCells('unstated', 'Not previewable', 'off');
  if (scheme === 'holds' || scheme === 'hold') return statusCells('unstated', 'Not previewable', 'holds');
  if (scheme !== 'linear' && scheme !== 'rpe' && scheme !== 'bodyweight') {
    return statusCells('unstated', 'Not previewable', scheme || 'unknown-scheme');
  }
  if (scheme === 'linear' && !profile.repsOnly && !(hWeight > 0)) {
    /* Mirrors forkPreviewTrajectory: weightless linear returns null. */
    return statusCells('unstated', 'Not previewable', 'no-load');
  }
  if (scheme !== 'linear' || profile.repsOnly) {
    /* The climbing branches step off reps: without a readable rep
       count (or a sane range) there is no exact next target. */
    if (hReps == null) return statusCells('unstated', 'Not previewable', 'missing-reps');
    if (!profile.repsOnly && profile.max < profile.min) {
      return statusCells('unstated', 'Not previewable', 'invalid-range');
    }
  }

  const isPct = profile.incrementType === 'pct';
  const incValue = profile.incrementValue;
  let curWeight = hWeight > 0 ? hWeight : 0;
  let curReps = hReps;
  /* FORK v1.992.22 (P2-8a, fix-list #32): a PERFORMED top set above
     a closed range's top is never adopted as the ongoing rep
     target — an AMRAP-style performance (6 reps in a 3–3 slot)
     used to ride every linear cell at stepped weights ("145 × 6",
     "150 × 6"). The engine clamps the same basis into the range
     on its linear success path (workout/progression.js) and
     forkPreviewTrajectory steps from that clamped suggestion;
     the grid now matches. Scoped three ways: performed histories
     only (a prescription states its own target and stays
     verbatim per FR-154), the linear scheme only (the rpe branch
     already treats an above-top count as the top — weight step,
     reps reset to min), and closed ranges only (an open range
     has no top to adopt past). */
  if (!fromPrescription && scheme === 'linear' && !profile.repsOnly
      && Number.isFinite(profile.max) && curReps != null && curReps > profile.max) {
    curReps = profile.max;
  }
  /* FORK v1.992.25 (P2-8b, fix-list #34): the below-floor mirror
     of the clamp above. A PERFORMED top set under a closed
     range's floor used to step UP by the increment every week
     (190 x 3 in a 6-12 range previewing 195 x 3, 200 x 3) while
     the live engine answers the same history with its
     back-into-range correction (formulas/e1rm.js backIntoRange,
     applied on the linear branch of progressionForExercise) —
     one exercise, two contradictory answers. Week 1 now IS the
     engine's correction, mirrored arithmetically (this core
     stays standalone, like the stepping above): RIR extends the
     top set's capacity (a missing RPE reads as 0, the engine's
     own fallback — the mounts pass the top set's logged RPE
     through on the history); capacity reaching the floor holds
     the load and targets the demonstrated capacity, capped at
     the range top; otherwise the load is
     re-derived from the Epley estimate at the range midpoint
     and snapped to the increment grid, never upward past the
     performed load (the #394 snap-up guard). Weeks 2+ step
     linearly from the corrected point, the same reading the
     prescription seed uses. Scoped like the clamp: performed
     histories, linear, non-repsOnly, closed ranges, loaded
     top sets only. The percent snap mirrors the engine's 5-unit
     grid in this core's own numeric space (display units at the
     mount); imperial is exact. */
  let seedFirst = false;
  if (!fromPrescription && scheme === 'linear' && !profile.repsOnly
      && Number.isFinite(profile.max) && curReps != null && curReps < profile.min
      && curWeight > 0) {
    const hRpe = forkPreviewGridNum(history.rpe);
    const rir = hRpe == null ? 0 : Math.max(0, 10 - hRpe);
    if (curReps + rir >= profile.min) {
      curReps = Math.min(profile.max, curReps + rir); /* plate batch 1, 2026-10-28 (D3): mirror of backIntoRange — the hold targets demonstrated capacity, capped at the range top. */
    } else {
      const e1 = curWeight * (1 + Math.min(curReps + rir, 15) / 30);
      const targetReps = Math.round((profile.min + profile.max) / 2);
      const raw = e1 / (1 + (targetReps + rir) / 30);
      const snap = (up) => isPct
        ? (up ? Math.ceil(raw / 5) : Math.round(raw / 5)) * 5
        : (incValue > 0
          ? (up ? Math.ceil(raw / incValue) : Math.round(raw / incValue)) * incValue
          : (up ? Math.ceil(raw) : Math.round(raw)));
      let seeded = snap(false);
      if (seeded < curWeight) seeded = snap(true);
      curWeight = Math.max(0, seeded);
      curReps = targetReps;
    }
    seedFirst = true;
  }
  /* FORK v1.991.33 (R1 item 5): a prescription-flagged history is
     the FIRST session's target itself — session 1 takes no step,
     and the trajectory steps from session 2 on. The cell shape
     mirrors each branch's own weight shaping.
     (`fromPrescription` is resolved at the top of this function
     since FORK v1.991.58.) */
  const totalSessions = weeks * sessionsPerWeek;
  const steps = [];
  for (let i = 0; i < totalSessions; i++) {
    if ((fromPrescription || seedFirst) && i === 0) {
      steps.push({ weight: scheme === 'bodyweight' ? null : (curWeight > 0 ? curWeight : null), reps: curReps });
    } else if (profile.repsOnly) {
      curReps += 1;
      steps.push({ weight: curWeight > 0 ? curWeight : null, reps: curReps });
    } else if (scheme === 'linear') {
      curWeight = isPct
        ? Math.round(curWeight * (1 + incValue / 100) * 2) / 2
        : curWeight + incValue;
      steps.push({ weight: curWeight, reps: curReps });
    } else {
      /* rpe / bodyweight */
      if (curReps < profile.max) {
        curReps += 1;
      } else {
        if (scheme !== 'bodyweight') {
          const inc = isPct
            ? (curWeight > 0 ? Math.round(curWeight * incValue / 100 * 2) / 2 : 0)
            : incValue;
          curWeight = curWeight > 0 ? curWeight + inc : 0;
        }
        curReps = profile.min;
      }
      steps.push({ weight: scheme === 'bodyweight' ? null : (curWeight || null), reps: curReps });
    }
  }

  /* One cell per week: the week's last session target. */
  const cells = [];
  for (let week = 1; week <= weeks; week++) {
    const step = steps[week * sessionsPerWeek - 1];
    cells.push({
      week,
      status: 'ok',
      weight: step.weight,
      reps: step.reps,
      label: forkPreviewGridLabel(step.weight, step.reps),
    });
  }
  return cells;
}

/* forkProgramPreviewGrid(program, histories, config) -> grid.
   Full contract in the header comment. Pure and total. */
function forkProgramPreviewGrid(program, histories, config) {
  const cfg = (config && typeof config === 'object') ? config : {};
  const weeksNum = forkPreviewGridNum(cfg.weeks);
  const weeks = weeksNum != null ? Math.min(12, Math.max(1, Math.trunc(weeksNum))) : 4;
  const sppRaw = cfg.sessionsPerWeekPerWorkout != null
    ? cfg.sessionsPerWeekPerWorkout
    : cfg.sessionsPerWeek;
  const sppNum = forkPreviewGridNum(sppRaw);
  const sessionsPerWeek = sppNum != null ? Math.min(7, Math.max(1, Math.trunc(sppNum))) : 1;

  const result = {
    programName: (program && typeof program.name === 'string') ? program.name : '',
    weeks,
    sessionsPerWeekPerWorkout: sessionsPerWeek,
    assumptions: forkPreviewGridAssumptions(sessionsPerWeek),
    rows: [],
  };

  const workouts = (program && Array.isArray(program.workouts)) ? program.workouts : [];
  workouts.forEach((workout, workoutIndex) => {
    if (!workout || typeof workout !== 'object') return;
    const listings = Array.isArray(workout.exercises)
      ? workout.exercises
      : (workout.template && Array.isArray(workout.template.exercises) ? workout.template.exercises : []);
    const workoutName = typeof workout.name === 'string' ? workout.name : '';
    for (const entry of listings) {
      const item = (entry && typeof entry === 'object') ? entry : {};
      const exerciseId = item.exerciseId != null ? item.exerciseId : (item.id != null ? item.id : null);
      const profile = forkPreviewGridProfile(item, program, cfg);
      /* FORK v1.991.33 (R1 item 5): the listing's own history wins
         over the shared map (see the header) — two occurrences of
         one exercise can start from different top sets. */
      const history = (item.history && typeof item.history === 'object')
        ? item.history
        : forkPreviewGridHistory(histories, exerciseId);
      result.rows.push({
        exerciseId,
        name: (typeof item.name === 'string' && item.name) ? item.name
          : (exerciseId != null ? String(exerciseId) : 'Exercise'),
        workoutName,
        workoutIndex,
        scheme: profile.scheme,
        min: profile.min,
        max: profile.max === Infinity ? null : profile.max,
        incrementType: profile.incrementType,
        incrementValue: profile.incrementValue,
        cells: forkPreviewGridCells(profile, history, weeks, sessionsPerWeek),
      });
    }
  });
  return result;
}
